code_sketch:
install(Sessions) {
    cookie<UserSession>("user_session", SessionStorageMemory()) {
        cookie.path = "/"
        cookie.maxAgeInSeconds = 1800
    }
}

get("/cart") {
    val s = call.sessions.get<UserSession>() ?: UserSession(id = "new", count = 0)
    call.sessions.set(s.copy(count = s.count + 1))     // persisted by the storage
    call.respondText("count=${s.count + 1}")
}
